def node(value, left, right):
    return llist(value, left, right)

tree = node(8, node(3, None, None), node(11, node(9, None, None), None))
print_llist(tree)

def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

print(factorial(3))

def factorial_iter(n, answer):
    if n == 0:
        return answer
    else:
        return factorial_iter(n - 1, n * answer)

print(factorial_iter(4, 1))

def factorial(n):
    return 1 if n == 0 else n * factorial(n - 1)

print(factorial(3))

def twice(f, x):
    return f(f(x))

print(twice(lambda n: n + 3, 4))

def choose(x):
    return x + 1 if x > 0 else 1 / 0

print(choose(3))
